// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface aiEnrichmentLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        versions: (configs: ConfigListResponseApi | null) => ConfigVersionApi[]
        selectedVersion: (versions: ConfigVersionApi[], selectedVersionId: string | null) => ConfigVersionApi | null
    }
}

export type aiEnrichmentLogicType = MakeLogicType<
    aiEnrichmentLogicValues,
    aiEnrichmentLogicActions,
    Record<string, any>,
    aiEnrichmentLogicMeta
>

export const aiEnrichmentLogic = kea<aiEnrichmentLogicType>([
    path(['products', 'growth', 'frontend', 'aiEnrichment', 'aiEnrichmentLogic']),
    actions({
        setSelectedLabel: (label: string | null) => ({ label }),
    }),
    loaders(() => ({
        labels: [
            null as LabelListResponseApi | null,
            {
                loadLabels: async () => await growthAiEnrichmentLabelsRetrieve(),
            },
        ],
        configs: [
            null as ConfigListResponseApi | null,
            {
                loadConfigs: async ({ label }: { label: string }) => await growthAiEnrichmentConfigsRetrieve({ label }),
            },
        ],
        activateResult: [
            null as ConfigVersionApi | null,
            {
                activateVersion: async (configId: string) =>
                    await growthAiEnrichmentActivateCreate({ config_id: configId }),
            },
        ],
    })),
    reducers({
        selectedLabel: [
            null as string | null,
            {
                setSelectedLabel: (_, { label }) => label,
            },
        ],
        selectedVersionId: [
            null as string | null,
            {
                setSelectedLabel: () => null,
                // Default to what's actually running in production, not the newest draft - a fresh
                // page load should show the active version.
                loadConfigsSuccess: (_, { configs }) => {
                    const versions = configs.results
                    return versions.find((version) => version.is_active)?.id ?? versions[0]?.id ?? null
                },
                activateVersionSuccess: (_, { activateResult }) => activateResult.id,
            },
        ],
    }),
    selectors({
        versions: [
            (s) => [s.configs],
            (configs: ConfigListResponseApi | null): ConfigVersionApi[] => configs?.results ?? [],
        ],
        selectedVersion: [
            (s) => [s.versions, s.selectedVersionId],
            (versions: ConfigVersionApi[], selectedVersionId: string | null): ConfigVersionApi | null =>
                versions.find((version) => version.id === selectedVersionId) ?? null,
        ],
    }),
    listeners(({ actions, values }) => ({
        setSelectedLabel: ({ label }) => {
            if (label) {
                actions.loadConfigs({ label })
            }
        },
        loadLabelsSuccess: ({ labels }) => {
            // Auto-enter the only label so the picker is skipped when there's nothing to pick.
            if (!values.selectedLabel && labels && labels.results.length === 1) {
                router.actions.replace(urls.aiEnrichment(labels.results[0].label))
            }
        },
        activateVersionSuccess: ({ activateResult }) => {
            lemonToast.success(`Activated version ${activateResult.version}.`)
            if (values.selectedLabel) {
                actions.loadConfigs({ label: values.selectedLabel })
            }
        },
        activateVersionFailure: () => {
            lemonToast.error('Failed to activate this version.')
        },
    })),
    afterMount(({ actions }) => {
        actions.loadLabels()
    }),
    urlToAction(({ actions, values }) => ({
        '/ai-enrichment': () => {
            if (values.selectedLabel !== null) {
                actions.setSelectedLabel(null)
            }
        },
        '/ai-enrichment/:label': ({ label }) => {
            if (label && label !== values.selectedLabel) {
                actions.setSelectedLabel(label)
            }
        },
    })),
])
